package domain

import "time"

// ShoppingList is a shopping list for a specific week (or several
// consecutive weeks). Only one list per (user, weekStart). week_count >= 1
// says how many weeks the list aggregates the ingredients over.
type ShoppingList struct {
	ID        int64
	UserID    int64
	WeekStart time.Time
	WeekCount int
	CreatedAt time.Time
}

// ShoppingListItem is a row generated by aggregating the plan
// automatically: a specific ingredient with the total quantity needed.
// Ingredient is filled by the repository on a full load.
type ShoppingListItem struct {
	ID             int64
	ShoppingListID int64
	IngredientID   int64
	TotalQuantity  float64
	Checked        bool
	SortOrder      int
	Ingredient     *Ingredient
}

// ShoppingUserItem is a manual row added by the user. Free text, kept
// across regenerations.
type ShoppingUserItem struct {
	ID             int64
	ShoppingListID int64
	Description    string
	QuantityText   string
	Checked        bool
	SortOrder      int
	CreatedAt      time.Time
}

// ShoppingListFull joins list + auto items + user items for rendering the
// shopping page.
type ShoppingListFull struct {
	ShoppingList
	Items     []ShoppingListItem
	UserItems []ShoppingUserItem
}
